def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances = {}
    frozen = set()
    history = []
    rejected = []

    def amount(token):
        if not token or any(c < "0" or c > "9" for c in token):
            return None
        # Parse in chunks to avoid Python's decimal string conversion limit.
        value = 0
        for i in range(0, len(token), 9):
            chunk = token[i:i + 9]
            value = value * (10 ** len(chunk)) + int(chunk)
        return value

    for index, operation in enumerate(ops):
        parts = operation.split(" ")
        verb = parts[0]
        success = False

        if verb == "undo" and len(parts) == 1:
            if history:
                entry = history.pop()
                kind = entry[0]
                if kind == "open":
                    del balances[entry[1]]
                    frozen.discard(entry[1])
                elif kind == "deposit":
                    balances[entry[1]] -= entry[2]
                elif kind == "withdraw":
                    balances[entry[1]] += entry[2]
                elif kind == "transfer":
                    balances[entry[1]] += entry[3]
                    balances[entry[2]] -= entry[3]
                elif kind == "freeze":
                    frozen.remove(entry[1])
                else:
                    frozen.add(entry[1])
                success = True

        elif verb in ("open", "deposit", "withdraw") and len(parts) == 3:
            account = parts[1]
            n = amount(parts[2])
            if account and n is not None:
                if verb == "open" and account not in balances:
                    balances[account] = n
                    history.append(("open", account))
                    success = True
                elif verb == "deposit" and n > 0 and account in balances:
                    balances[account] += n
                    history.append(("deposit", account, n))
                    success = True
                elif (
                    verb == "withdraw"
                    and n > 0
                    and account in balances
                    and account not in frozen
                    and balances[account] >= n
                ):
                    balances[account] -= n
                    history.append(("withdraw", account, n))
                    success = True

        elif verb == "transfer" and len(parts) == 4:
            source, destination = parts[1], parts[2]
            n = amount(parts[3])
            if (
                n is not None
                and n > 0
                and source != destination
                and source in balances
                and destination in balances
                and source not in frozen
                and balances[source] >= n
            ):
                balances[source] -= n
                balances[destination] += n
                history.append(("transfer", source, destination, n))
                success = True

        elif verb in ("freeze", "unfreeze") and len(parts) == 2:
            account = parts[1]
            if account in balances:
                if verb == "freeze" and account not in frozen:
                    frozen.add(account)
                    history.append(("freeze", account))
                    success = True
                elif verb == "unfreeze" and account in frozen:
                    frozen.remove(account)
                    history.append(("unfreeze", account))
                    success = True

        if not success:
            rejected.append(index)

    return balances, rejected
